from typing import Dict, Any

class FinancialRiskModel(SimulationModel):
    def run_simulation(self, input_data: Dict[str, Any]) -> Dict[str, Any]:
        amount = input_data.get("transaction_amount", 0)
        credit_score = input_data.get("user_credit_score", 0)
        risk_factor = 0.1  # Example risk calculation parameter
        
        risk_score = amount * risk_factor
        risk_level = "high" if risk_score > credit_score else "low"
        
        return {
            "risk_score": risk_score,
            "risk_level": risk_level,
            "input_valid": all(key in input_data for key in ["transaction_amount", "user_credit_score"])
        }

