from typing import Dict, Type, Any
from .base import SimulationModel

class SimulationEngine:
    def __init__(self):
        self._models: Dict[str, Type[SimulationModel]] = {}
    
    def register_model(self, name: str, model_class: Type[SimulationModel]):
        self._models[name] = model_class
    
    def run_simulation(self, model_name: str, input_data: Dict[str, Any]) -> Dict[str, Any]:
        if model_name not in self._models:
            raise ValueError(f"Unknown simulation model: {model_name}")
        
        model = self._models[model_name]()
        return model.run_simulation(input_data)

