import unittest
from cerebrum.models.base import SimulationModel
from cerebrum.models.financial_risk import FinancialRiskModel

class TestSimulationModel(unittest.TestCase):
    def test_abstract_class_cannot_be_instantiated(self):
        with self.assertRaises(TypeError):
            SimulationModel()
    
    def test_financial_risk_model_output(self):
        model = FinancialRiskModel()
        input_data = {
            "transaction_amount": 10000,
            "user_credit_score": 700
        }
        result = model.run_simulation(input_data)
        self.assertEqual(result["risk_level"], "high")
        self.assertEqual(result["risk_score"], 1000.0)
        self.assertTrue(result["input_valid"])

