import unittest
from cerebrum.engine import SimulationEngine
from cerebrum.models.financial_risk import FinancialRiskModel

class TestSimulationEngine(unittest.TestCase):
    def test_model_registration_and_execution(self):
        engine = SimulationEngine()
        engine.register_model("financial_risk", FinancialRiskModel)
        
        input_data = {
            "transaction_amount": 5000,
            "user_credit_score": 600
        }
        result = engine.run_simulation("financial_risk", input_data)
        self.assertEqual(result["risk_level"], "high")
        self.assertTrue(result["input_valid"])
    
    def test_unknown_model_raises_error(self):
        engine = SimulationEngine()
        with self.assertRaises(ValueError):
            engine.run_simulation("unknown_model", {})

